export default function Pill({
  children,
  solid,
  lg,
  glass
}: {
  children: ReactNode
  solid?: boolean
  lg?: boolean
  glass?: boolean
}) {
  return (
    <span
      className={`font-medium rounded-full transition-colors ${lg ? 'text-xs px-2.5 py-1.5' : 'text-[11px] px-2 py-0.5'} ${
        solid ? 'bg-fg text-ink-900' : `bg-fg/[0.06] ${glass ? 'text-fg/45' : 'text-fg-muted'}`
      }`}
    >
      {children}
    </span>
  )
}

